Let $f,g\in L_\textup{loc}^1(\Omega)$. We say that $g$ is the $\alpha$-th \textit{weak} or \textit{distributional} derivative of $f$ if and only if
\begin{equation*}
\int_{\Omega}g\varphi\,dx=(-1)^{|\alpha|}\int_{\Omega}fD^\alpha\varphi\,dx \quad \text{ for every } \varphi\in\mathcal{C}_c^\infty(\Omega).
\end{equation*}
In such a case we write $g=:D^\alpha f$.

\label{D:Sobo}
Let $k\ge1$ an integer and $1\le p\le\infty$. We define the Sobolev space
\begin{equation*}
W^{k,p}(\Omega):=\Set{f\in L^p(\Omega)|D^\alpha f\in L^p(\Omega) \text{ for all } \alpha\in\mathbb{N}^N \text{ with } |\alpha|\le k}.
\end{equation*}

\label{L:all}
\begin{itemize}
	\item [(i)] The following are equivalent:
	\begin{itemize}
		\item [-] $\Phi\in\Delta_2$,
		\item [-] there exists $K>1$ such that $t\Phi'(t)\le K\Phi(t)$ for every $t\in\mathbb{R}$,
		\item [-] there exists $K'>1$ such that $t\Psi'(t)\ge K'\Psi(t)$ for every $t\in\mathbb{R}$,
		\item [-] $\Psi\in\nabla_2$.
	\end{itemize}
	\item [(ii)] For every $\mathbf{U}\in L^\Phi$, $\mathbf{V}\in L^\Psi$ there holds
	$$\int_{\mathbb{R}^3}|\mathbf{U}||\mathbf{V}|\,dx\le\min\{|\mathbf{U}|_{\Phi,1}|\mathbf{V}|_{\Psi},|\mathbf{U}|_{\Phi}|\mathbf{V}|_{\Psi,1}\}.$$
	\item [(iii)] Let $\mathbf{U}_n$, $\mathbf{U}\in L^\Phi$. Then $|\mathbf{U}_n-\mathbf{U}|_\Phi\to 0$ implies that $\int_{\mathbb{R}^3}\Phi(|\mathbf{U}_n-\mathbf{U}|)\,dx\to 0$. If $\Phi\in\Delta_2$, then $\int_{\mathbb{R}^3}\Phi(|\mathbf{U}_n-\mathbf{U}|)\,dx\to 0$ implies $|\mathbf{U}_n-\mathbf{U}|_\Phi\to 0$.
	\item [(iv)] Let $X\subset L^\Phi$. Then $X$ is bounded if $\Set{\int_{\mathbb{R}^3}\Phi(\left|\mathbf{U}\right|)\,dx|\mathbf{U}\in X}$ is bounded. If $\Phi\in\Delta_2$, then the opposite implication holds.
\end{itemize}

\label{L:Hel}
$\mathcal{V}$ and $\mathcal{W}$ are closed subspaces of $\mathcal{D}(\textup{curl},\Phi)$  and
\begin{equation}\label{e-Hel}
\mathcal{D}(\textup{curl},\Phi)=\mathcal{V}\oplus \mathcal{W}.
\end{equation}
Moreover, $\mathcal{V}\subset\mathcal{D}$ and the norms $\|\cdot\|_{\mathcal{D}}$ and $\|\cdot\|_{\textup{curl},\Phi}$ are equivalent in $\mathcal{V}$.

\label{P:var}
If $\mathbf{U}=v+w\in\mathcal{V}\oplus\mathcal{W}$, then the following are equivalent:
\begin{itemize}
	\item [(i)] $(v,w)$ is a critical point of $J$;
	\item [(ii)] $\mathbf{U}$ is a critical point of $E$;
	\item [(iii)] $\mathbf{U}$ is a (weak) solution to \eqref{e-Curl}.
\end{itemize}

Let $u\in\mathcal{N}$. In view of (I8), we get by explicit computations
	\begin{equation*}
	J(tu+v)=J(tu+v)-J'(u)\left(\frac{t^2-1}{2}u+tv\right)\le J(u)
	\end{equation*}
	for every $t\geq 0$ and every $v\in X^-$.

\label{T:Link1}
	Suppose $J \in \mathcal{C}^1(X)$ satisfies (I1)--(I8). Then:
	\begin{itemize}
		\item[(a)] $c_{\mathcal{M}}\ge a>0$ and $\mathcal{J}$ has a Cerami sequence $u_n\in X^+$ at the level $c_\mathcal{M}$. 
		\item[(b)] $c_{\mathcal{M}}=c_{\mathcal{N}}:= \inf_\mathcal{N} J$.
	\end{itemize}

\textit{(a)} Set
	\begin{equation}\label{e-Gamma_Phi}
	\Sigma := \Set{\sigma\in\mathcal{C}([0,1],X^+)|\sigma(0)=0, \|\sigma(1)\|>r,
	\mathcal{J}(\sigma(1))<0}.
	\end{equation}
	Observe that $\mathcal{J}$ has the mountain pass geometry and $\Gamma$ and $\Sigma$ are related as follows: if $\gamma\in\Gamma$, then $\gamma^+\in\Sigma$ and $J\bigl(\gamma(t)\bigr)=\mathcal{J}\bigl(\gamma^+(t)\bigr)$; if $\sigma\in\Sigma$, then $m\circ\sigma\in\Gamma$ and $\mathcal{J}\bigl(\sigma(t)\bigr) = J\bigl(m\bigl(\sigma(t)\bigr)\bigr)$. Hence the mountain pass value for $\mathcal{J}$ is given by
	\begin{equation}\label{e-cm}
	c_{\mathcal{M}}=\inf_{\sigma\in\Sigma}\max_{t\in [0,1]}J\bigl(m\bigl(\sigma(t)\bigr)\bigr)=\inf_{\sigma\in\Sigma}\max_{t\in [0,1]}\mathcal{J}\bigl(\sigma(t)\bigr) \ge a > 0.
	\end{equation} 
	The existence of a Cerami sequence $u_n\in X^+$ for $\mathcal{J}$ at the level $c_\mathcal{M}$ then follows.
			
	The map $u\mapsto m(u)$ is a homeomorphism between $\mathcal{N}_0$ and $\mathcal{N}$ and, since $\mathcal{J}(u)=J\bigl(m(u)\bigr)$, $c_{\mathcal{N}_0}=c_{\mathcal{N}}$. For $u\in X^+\setminus\{0\}$, consider $\mathcal{J}(tu)$, $t>0$. From Lemma \ref{L:infty}, $\mathcal{J}(tu)\to-\infty$ as $t\to\infty$. Hence $\max_{t > 0}\mathcal{J}(tu)\geq a$ exists. If $t_1u,t_2u\in \mathcal{N}_0$, then $m(t_1u),m(t_2u)\in\mathcal{N}$, so from Lemma \ref{L:max}, $\mathcal{J}(t_1u) =\mathcal{J}(t_2u)$. Consequently, there exist $0 < t_\textup{min} \le t_\textup{max}$ such that $\mathcal{J}(tu)\in\mathcal{N}_0$ if and only if $t\in[t_\textup{min},t_\textup{max}]$ and $\mathcal{J}(tu)$ has the same value for those $t$. Hence $\mathcal{J}'(tu)(u)>0$ for $0<t<t_\textup{min}$ and $\mathcal{J}'(tu)(u)<0$ for $t>t_\textup{max}$.  It follows that $X^+\setminus \mathcal{N}_0$ consists of two connected components, hence each path in $\Sigma$ must intersect $\mathcal{N}_0$. Therefore $c_{\mathcal{M}}\ge c_{\mathcal{N}_0}$. Since $c_{\mathcal{N}_0} = \inf_{u\in X^+\setminus\{0\}}\max_{t>0}\mathcal{J}(tu)$, \eqref{e-cm} implies $c_{\mathcal{M}} = c_{\mathcal{N}_0} = c_{\mathcal{N}}$. Note in particular that $\mathcal{J}\ge 0$ on $B_r$, where $r$ is given in (I6), so the condition $\|\sigma(1)\|>r$ in the definition of $\Sigma$ is redundant because it must necessarily hold if $\mathcal{J}\bigl(\sigma(1)\bigr)<0$.

\label{T:CrticMulti}
	Suppose $J \in \mathcal{C}^1(X)$ satisfies (I1)--(I8) and $\dim(X^+)=\infty$.
	\begin{itemize}
		\item [(a)] If  $(M)_0^{c_\mathcal{M}+\varepsilon}$ holds for some $\varepsilon>0$, then either $c_{\mathcal{M}}$ is attained by a critical point or there exists a sequence of critical values $c_n$ such that $c_n>c_{\mathcal{M}}$ and $c_n\to c_{\mathcal{M}}$ as $n\to\infty$.
		\item [(b)] If $(M)_0^{\beta}$ holds for every $\beta>0$ and $J$ is even, 
		then $J$ has infinitely many distinct critical orbits.
	\end{itemize}

\label{L:index}
	Let $A,B\in\mathcal{A}$.
	\begin{itemize}
	\item [(i)] If $A\subset B$, then $i^*(A)\le i^*(B)$.
	\item [(ii)] $i^*(A\cup B)\le i^*(A)+\gamma(B)$.
	\item [(iii)] If $g\in \mathcal{H}$, then $i^*(A)\le i^*\bigl(g(A)\bigr)$.
	\item [(iv)] For every $k$-dimensional subspace $X_k\subset X^+$ there exists $R_0>0$ such that $i^*(X_k\cap\overline B_R)\ge k$ if $R\ge R_0$.
\end{itemize}

\label{L:Conv}
	Suppose that $v_n\in\mathcal{D}$ is bounded and for some $R>\sqrt{3}$
	\begin{equation}\label{e-LionsCond1}
	\lim_n\sup_{y\in \mathbb{Z}^3}\int_{B(y,R)}|v_n|^2\,dx=0.
	\end{equation}
	Then  
	$$\lim_n\int_{\mathbb{R}^3}\Phi(|v_n|)\,dx=0.$$

\label{L:DefofW}
	(a) For every $v\in L^{\Phi}$ there exists a unique $w(v)\in \mathcal{W}$ such that
	\begin{equation}\label{e-DefofW(u)}
	I\bigl(v,w(v)\bigr)=\min_{w\in\mathcal{W}}I(v,w).
	\end{equation}
	Moreover, $w\colon L^{\Phi}\to\mathcal{W}$ is continuous.\\
	(b) $w$ maps bounded sets into bounded sets and $w(0)=0$.

\label{L:Discreteness}
	Let $\beta\ge c_{\mathcal{N}}$ and suppose that $\mathcal{K}$ has a finite number of distinct orbits.  
	If $u_n,v_n\in\mathcal{V}$ are two Cerami sequences for $J\circ m$ such that $0\le\liminf_nJ\bigl(m(u_n)\bigr)\le \limsup_nJ\bigl(m(u_n)\bigr)\le\beta$, $0\le\liminf_nJ\bigl(m(v_n)\bigr)\le \limsup_nJ\bigl(m(v_n)\bigr)\le\beta$ and $\liminf_n\|u_n-v_n\|_{\mathcal{D}}< \kappa$, then $\lim_n\|u_n-v_n\|_{\mathcal{D}}=0$.

Let $m(u_n)=(u_n,w^1_n)$, $m(v_n)=(v_n,w^2_n)$. From Lemma \ref{L:Coercive}, $m(u_n)$ and $m(v_n)$ are bounded.
	We first consider the case 
	\begin{equation}
	\label{e-pqconvergence}
	\lim_n|u_n-v_n|_{\Phi}=0
	\end{equation}
	and  prove that
	\begin{equation}
	\label{e-convergence}
	\lim_n\|u_n-v_n\|_\mathcal{D}=0.
	\end{equation}
	From (F3) and Lemmas \ref{L:all} \textit{(ii)} and \ref{L:forC1} we have
	\[
	\begin{split}
	\|u_n-v_n\|_{\mathcal{D}}^2 = \, & J'\bigl(m(u_n)\bigr)(u_n-v_n,0)-J'\bigl(m(v_n)\bigr)(u_n-v_n,0)\\
	& +\int_{\mathbb{R}^3} \Bigl(f\bigl(x,m(u_n)\bigr)-f\bigl(x,m(v_n)\bigr)\Bigr)\cdot(u_n-v_n)\,dx\le\\
	\le \, & o(1)+\int_{\mathbb{R}^3}\Bigl(\big|f\bigl(x,m(u_n)\bigr)\big|+\big|f\bigl(x,m(v_n)\bigr)\big|\Bigr)|u_n-v_n|\,dx\\
	\le \, & o(1)+c_1\int_{\mathbb{R}^3}\Bigl(\Phi'\bigl(|m(u_n)|\bigr)+\Phi'\bigl(|m(v_n)|\bigr)\Bigr)|u_n-v_n|\,dx \\
	\le \, & o(1)+ C\Bigl(\big|\Phi'\bigl(|m(u_n)|\bigr)\big|_\Psi+\big|\Phi'\bigl(|m(v_n)|\bigr)\big|_\Psi\Bigr)|u_n-v_n|_{\Phi}\to0
	\end{split}
	\]
	which gives \eqref{e-convergence}.
	
	Suppose now \eqref{e-pqconvergence} does not hold. From Lemmas \ref{L:all} \textit{(iii)} and \ref{L:Conv}, for a fixed $R>\sqrt{3}$ there exist $\varepsilon>0$ and $y_n\in\mathbb{Z}^3$ such that, up to a subsequence,
	\begin{equation}
	\label{e-boundedaway}
	\int_{B(y_n,R)}|u_n-v_n|^2\,dx\ge\varepsilon
	\end{equation}
	(cf. the proof of Lemma \ref{L:Coercive}). As $J$ is $\mathbb{Z}^3$-invariant, we can assume $y_n=0$. Since $m(u_n)$ and $m(v_n)$ are bounded, up to a subsequence
	\begin{equation}
	\label{e-weakconvergence}
	(u_n,w^1_n)\rightharpoonup(u,w^1)\hbox{ and }(v_n,w^2_n)\rightharpoonup(v,w^2)\quad\hbox{in }\mathcal{V}\times\mathcal{W} 
	\end{equation}
	for some $(u,w^1),(v,w^2)\in \mathcal{V}\times\mathcal{W}$. Since $u_n\to u$ and $v_n\to v$ in $L^2_\textup{loc}(\mathbb{R}^3,\mathbb{R}^3)$, $u\ne v$ according to \eqref{e-boundedaway}.
	From Corollary \ref{C:Jweaklycont} and \eqref{e-weakconvergence} we infer that
	\[
	J'(u,w^1)=J'(v,w^2)=0.
	\]
	Thus
	\[
	\liminf_n\|u_n - v_n\|_{\mathcal{D}} \ge\|u - v\|_{\mathcal{D}}\ge \kappa
	\]
	which is a contradiction.

\label{C:V1}
	Suppose that $K=2$ and $h$ satisfies \eqref{e-fgh}.
	\begin{itemize}
		\item [(a)] If (F1)--(F4) hold, then \eqref{e-curlsym} has infinitely many geometrically distinct solutions in $\mathcal{D}_{\mathcal{F}}$, one of which is a ground state solution in $\mathcal{D}_{\mathcal{F}}$.
		\item [(b)] If (F1)--(F2), (F5) hold and $h$ does not depend on $y$, then \eqref{e-curlsym} has a nontrivial solution $\mathbf{U}\in\mathcal{D}_{\mathcal{F}}$.
	\end{itemize}

\label{C:V2}
There exists a ground state solution in $\mathcal{D}_{\mathcal{F}}$ to
\begin{equation}\label{e-crit}
\nabla\times\nabla\times\mathbf{U}=|\mathbf{U}|^{2^*-2}\mathbf{U} \quad \text{in } \mathbb{R}^N.
\end{equation}

\label{L:dec}
	For every $\mathbf{U}\in\textup{Fix}(\mathcal{S}\mathcal{O})$ there exist $\mathbf{U}_\rho,\mathbf{U}_\tau,\mathbf{U}_{\zeta,i}\in\textup{Fix}(\mathcal{S}\mathcal{O})$, $i\in\{3,\dots,N\}$, such that for every $x\in\mathbb{R}^N_*$ at which $\mathbf{U}(x)$ is defined
	\begin{itemize}
		\item $\mathbf{U}_\rho(x)$ is the orthogonal projection of $\mathbf{U}(x)$ onto $\textup{span}\{(x_1,x_2,0)\}$,
		\item $\mathbf{U}_\tau(x)$ is the orthogonal projection of $\mathbf{U}(x)$ onto $\textup{span}\{(-x_2,x_1,0)\}$,
		\item $\mathbf{U}_{\zeta,i}(x)$ is the orthogonal projection of $\mathbf{U}(x)$ onto $\textup{span}\{e_i\}$,
	\end{itemize}
	and $\nabla\mathbf{U}_\rho(x),\nabla\mathbf{U}_\tau(x),\nabla\mathbf{U}_{\zeta,i}(x)$ are pairwise orthogonal in $\mathbb{R}^{N\times N}\simeq\mathbb{R}^{N^2}$, $i\in\{3,\dots,N\}$. In particular, $\mathbf{U}=\mathbf{U}_\rho+\mathbf{U}_\tau+\sum_{i=3}^N\mathbf{U}_{\zeta,i}$.

For $\mathbf{U}\in\textup{Fix}(\mathcal{S}\mathcal{O})$ we write $\mathbf{U}=(\mathbf{U}_1,\dots,\mathbf{U}_N)$. For $x\in\mathbb{R}^N_*$ let $\mathbf{U}_\rho(x)$, $\mathbf{U}_\tau(x)$, and $\mathbf{U}_{\zeta,i}(x)$ be the orthogonal projections as in the statement. Then
	\begin{equation*}\begin{split}
	\mathbf{U}_\rho(x) = U_\rho(x)
	\begin{pmatrix}
	x_1 \\ x_2 \\ 0
	\end{pmatrix}
	= \frac{x_1\mathbf{U}_1(x)+x_2\mathbf{U}_2(x)}{r^2}
	\begin{pmatrix}
	x_1 \\ x_2 \\ 0
	\end{pmatrix},
	\\
	\mathbf{U}_\tau(x) = U_\tau(x)
	\begin{pmatrix}
	-x_2 \\ x_1 \\ 0
	\end{pmatrix}
	= \frac{-x_2\mathbf{U}_1(x)+x_1\mathbf{U}_2(x)}{r^2}
	\begin{pmatrix}
	-x_2 \\ x_1 \\ 0
	\end{pmatrix},
	\\
	\mathbf{U}_{\zeta,i}(x) = U_{\zeta,i}(x)e_i = \mathbf{U}_i(x)e_i.
	\end{split}\end{equation*}
	
	We prove that $U_\rho$, $U_\tau$, and $U_{\zeta,i}$ are $\mathcal{S}\mathcal{O}$-invariant. This is trivial for $U_{\zeta,i}$ because $i\ge3$; moreover, note that
	\[\begin{split}
	U_\rho(x) & = \frac1{r^2}
	\begin{pmatrix}
	\mathbf{U}_1(x) & \mathbf{U}_2(x)
	\end{pmatrix}
	\begin{pmatrix}
	x_1 \\ x_2
	\end{pmatrix},
	\\
	U_\tau(x) & = \frac1{r^2}
	\begin{pmatrix}
	\mathbf{U}_1(x) & \mathbf{U}_2(x)
	\end{pmatrix}
	\begin{pmatrix}
	0 & -1 \\ 1 & 0
	\end{pmatrix}
	\begin{pmatrix}
	x_1 \\ x_2
	\end{pmatrix},
	\end{split}\]
	therefore, exploiting that $\mathcal{S}\mathcal{O}(2)$ is abelian,
	\[\begin{split}
	U_\rho(\widetilde{g}x) & = \frac1{r^2}
	\begin{pmatrix}
	\mathbf{U}_1(x) & \mathbf{U}_2(x)
	\end{pmatrix}
	g^Tg
	\begin{pmatrix}
	x_1 \\ x_2
	\end{pmatrix}
	\\
	& = \frac1{r^2}
	\begin{pmatrix}
	\mathbf{U}_1(x) & \mathbf{U}_2(x)
	\end{pmatrix}
	\begin{pmatrix}
	x_1 \\ x_2
	\end{pmatrix}
	=U_\rho(x),
	\\
	U_\tau(\widetilde{g}x) & = \frac1{r^2}
	\begin{pmatrix}
	\mathbf{U}_1(x) & \mathbf{U}_2(x)
	\end{pmatrix}
	g^Tg
	\begin{pmatrix}
	0 & -1 \\ 1 & 0
	\end{pmatrix}
	\begin{pmatrix}
	x_1 \\ x_2
	\end{pmatrix}
	\\
	& = \frac1{r^2}
	\begin{pmatrix}
	\mathbf{U}_1(x) & \mathbf{U}_2(x)
	\end{pmatrix}
	\begin{pmatrix}
	0 & -1 \\ 1 & 0
	\end{pmatrix}
	\begin{pmatrix}
	x_1 \\ x_2
	\end{pmatrix}
	=U_\tau(x)
	\end{split}\]
	for every $g\in\mathcal{S}\mathcal{O}(2)$ and a.e. $x\in\mathbb{R}^N$.
	
	Now we prove that $\mathbf{U}_\rho,\mathbf{U}_\tau,\mathbf{U}_{\zeta,i}\in\mathcal{D}^{1,2}(\mathbb{R}^N,\mathbb{R}^N)$. From their very definition, $\mathbf{U}_\rho,\mathbf{U}_\tau,\mathbf{U}_{\zeta,i}\in L^6(\mathbb{R}^N,\mathbb{R}^N)\cap H^1_\textup{loc}(\mathbb{R}^N_*,\mathbb{R}^N)$. In what follows we denote by $\partial_j\mathbf{U}_\rho|_{\mathbb{R}^N_*}$ the partial derivative along $x_j$ of $\mathbf{U}_\rho$ in $\mathbb{R}^N_*$ in the sense of distributions and by $\partial_j\mathbf{U}_\rho$ the function defined a.e. in $\mathbb{R}^N$ that represents it, i.e.
	\begin{equation}\label{e-weakder}
	\int_{\mathbb{R}^N}\partial_j\mathbf{U}_\rho|_{\mathbb{R}^N_*}\cdot\varphi\,dx=-\int_{\mathbb{R}^N}\mathbf{U}_\rho\cdot\partial_j\varphi\,dx
	\end{equation}
	for every $\varphi\in\mathcal{C}_c^\infty(\mathbb{R}^N_*,\mathbb{R}^N)$; similar notations are used for $\mathbf{U}_\tau$ and $\mathbf{U}_{\zeta,i}$. With a small abuse of notation, the symbol $\cdot$ will stand for the scalar product both in $\mathbb{R}^N$ and in $\mathbb{R}^{N\times N}\simeq\mathbb{R}^{N^2}$.
	
	It is obvious that for every $i,j\in\{3,\dots,N\}$ and a.e. $x\in\mathbb{R}^N$
	\[
	\nabla\mathbf{U}_{\zeta,i}(x)\cdot\nabla\mathbf{U}_{\zeta,j}(x)=\nabla\mathbf{U}_{\zeta,i}(x)\cdot\nabla\mathbf{U}_\rho(x)=\nabla\mathbf{U}_{\zeta,i}(x)\cdot\nabla\mathbf{U}_\tau(x)=0.
	\]
	Moreover, by explicit computations,
	\[\begin{split}
	\nabla\mathbf{U}_\rho(x)\cdot\nabla\mathbf{U}_\tau(x) = \, & \nabla[U_\rho(x)x_2]\cdot\nabla[U_\tau(x)x_1]-\nabla[U_\rho(x)x_1]\cdot\nabla[U_\tau(x)x_2]\\
	= \, & x_2U_\tau(x)\partial_1U_\rho(x)+x_1U_\rho(x)\partial_2U_\tau(x)\\
	& -x_1U_\tau(x)\partial_2U_\rho(x)-x_2U_\rho(x)\partial_1U_\tau(x)=0,
	\end{split}\]
	where the last equality follows from the fact that the $\mathcal{S}\mathcal{O}$-invariance of $U_\rho$ implies $x_1\partial_2U_\rho=x_2\partial_1U_\rho$ (and likewise for $U_\tau$).
	
	This yields
	\begin{equation*}
	|\nabla\mathbf{U}|^2=|\nabla\mathbf{U}_\rho|^2+|\nabla\mathbf{U}_\tau|^2+\sum_{i=3}^N|\nabla\mathbf{U}_{\zeta,i}|^2 \quad \text{ a.e. in } \mathbb{R}^N,
	\end{equation*}
	whence for every $i\in\{3,\dots,N\}$ and every $j\in\{1,\dots,N\}$
	\[
	\partial_j\mathbf{U}_\rho,\partial_j\mathbf{U}_\tau,\partial_j\mathbf{U}_{\zeta,i}\in L^2(\mathbb{R}^N,\mathbb{R}^N),
	\]
	hence the proof will be complete once we show that $\partial_j\mathbf{U}_\rho|_{\mathbb{R}^N_*}$ coincide with the distributional derivative (along $x_j$) of $\mathbf{U}_\rho$ in $\mathbb{R}^N$, i.e., \eqref{e-weakder} holds for every $\varphi\in\mathcal{C}_c^\infty(\mathbb{R}^N,\mathbb{R}^N)$, and likewise for $\mathbf{U}_\tau$ and $\mathbf{U}_{\zeta,i}$. For $\varepsilon>0$ consider $\eta_\varepsilon\in\mathcal{C}^\infty(\mathbb{R}^N,\mathbb{R})$ such that
	\[
	\eta_\varepsilon(x)=0 \text{ for } |r|\le\frac\varepsilon2, \quad \eta_\varepsilon(x)=1 \text{ for } r\ge\varepsilon, \quad 0\le\eta_\varepsilon\le1, \quad |\nabla\eta_\varepsilon|\le\frac4\varepsilon.
	\]
	Let $\varphi\in\mathcal{C}_c^\infty(\mathbb{R}^N,\mathbb{R}^N)$ and set $\varphi_\varepsilon:=\eta_\varepsilon\varphi\in\mathcal{C}_c^\infty(\mathbb{R}^N_*,\mathbb{R}^N)$. There holds
	\begin{equation}\label{e-eps1}
	\begin{split}
	\int_{\mathbb{R}^N}\partial_j\mathbf{U}_\rho\cdot\varphi_\varepsilon\,dx & = -\int_{\mathbb{R}^N}\mathbf{U}_\rho\cdot\partial_j\varphi_\varepsilon\,dx\\
	& = -\int_{\mathbb{R}^N}\eta_\varepsilon\mathbf{U}_\rho\cdot\partial_j\varphi\,dx-\int_{\mathbb{R}^N}\partial_j\eta_\varepsilon\mathbf{U}_\rho\cdot\varphi.
	\end{split}\end{equation}
	From the dominated convergence theorem,
	\begin{equation}\label{e-eps2}
	\begin{split}
	\lim_{\varepsilon\to0^+}\int_{\mathbb{R}^N}\partial_j\mathbf{U}_\rho\cdot\varphi_\varepsilon\,dx=\int_{\mathbb{R}^N}\partial_j\mathbf{U}_\rho|_{\mathbb{R}^N_*}\cdot\varphi\,dx\\
	\lim_{\varepsilon\to0^+}\int_{\mathbb{R}^N}\eta_\varepsilon\mathbf{U}_\rho\cdot\partial_j\varphi\,dx=\int_{\mathbb{R}^N}\mathbf{U}_\rho\cdot\partial_j\varphi\,dx.
	\end{split}\end{equation}
	Let $R>0$ such that $\varphi(x)=0$ for $|x|\ge R$ and set $\Omega_\varepsilon:=B_R\cap\{r<\varepsilon\}$ and observe that                                                     
	$|\Omega_\varepsilon|\le C\varepsilon^2$ for some $C>0$ depending only on $N$ and $R$, thus
	\begin{equation}\label{e-eps3}
	\begin{split}
	\left|\int_{\mathbb{R}^N}\partial_j\eta_\varepsilon\mathbf{U}_\rho\cdot\varphi\,dx\right| & \le\|\varphi\|_\infty\frac4\varepsilon\int_{\Omega_\varepsilon}|\mathbf{U}_\rho|\,dx\\
	& \le\|\varphi\|_\infty\frac4\varepsilon|\Omega_\varepsilon|^{\frac{N+2}{2N}}|\mathbf{U}_\rho|_{2^*}\to0
	\end{split}\end{equation}
	as $\varepsilon\to0^+$. Letting $\varepsilon\to0^+$ in \eqref{e-eps1} and using \eqref{e-eps2} and \eqref{e-eps3} we have the desired result. Finally, similar computations hold for $\mathbf{U}_\tau$ and $\mathbf{U}_{\zeta,i}$.

\label{L:Lions}
	Suppose that $u_n\in\mathcal{D}^{1,2}(\mathbb{R}^N)$ is bounded and $\mathcal{S}\mathcal{O}$-invariant and for every $R>0$
	\begin{equation}\label{e-LionsCond}
	\lim_n\sup_{z\in \mathbb{R}^{N-K}} \int_{B((0,z),R)} u_n^2\,dx=0.
	\end{equation}
	Then
	\[
	\lim_n\int_{\mathbb{R}^N}\Phi(u_n)\,dx=0
	\]
	for every continuous function $\Phi\colon\mathbb{R}\to [0,\infty[$ such that
	\begin{equation}\label{e-LionsPhi}
	\displaystyle\lim_{s\to 0}\frac{\Phi(s)}{|s|^{2^*}}=\lim_{|s|\to\infty}\frac{\Phi(s)}{|s|^{2^*}}=0.
	\end{equation}

\label{L:Mbeta}
	Suppose $f$ satisfies (F3) and (F4).
	\begin{itemize}
		\item [(a)] For every $\beta>0$ there exists $M_\beta>0$ such that $\limsup_n\|u_n\|\le M_\beta$ for every $u_n\subset X_{\mathcal{S}\mathcal{O}}$ such that $J(u_n)\le\beta$ for $n\gg1$ and $\lim_n(1+\|u_n\|)J'(u_n)=0$.
